"""Annotate the read-only inventory audit with manually reviewed scope decisions."""
from pathlib import Path
import collections, fnmatch, hashlib, json, subprocess
OUT=Path(__file__).resolve().parent
ROOT=OUT.parents[4]
def read(p):return json.loads((ROOT/p).read_text(encoding='utf-8-sig'))
def sha(p):return hashlib.sha256((ROOT/p).read_bytes()).hexdigest()
def git(*args):return subprocess.check_output(['git',*args],cwd=ROOT).decode().strip()
report=read(OUT.relative_to(ROOT)/'inventory-audit.json')
target=report['target_source']
catalog={x['id']:x for x in read('spec/v2.0/contracts/acceptance.json')['cases']}

