for row in report['cases']:
 c=row['case']; spec=catalog[c]
 row['title']=spec['title'];row['required_mode']=spec.get('mode') or spec.get('environment_mode')
 if not row['required_mode']:
  row['required_mode']=spec.get('modes')
 row['required_assertions']=[x['id'] for x in spec['assertions']]
 row['inventory_completeness']='UNKNOWN_NOT_A_PROVEN_TRANSITIVE_DEPENDENCY_CLOSURE'
 if c in group_by_case:
  name,g=group_by_case[c]; row['scope_group']=name
  changed=row.get('git_changes_since_envelope',[])
  row['direct_scope_changed_paths']=[p for p in changed if matches(p,g['patterns'])]
  row['direct_production_changed_paths']=[p for p in row['direct_scope_changed_paths'] if production(p)]
  row['shared_scope_changed_paths']=[p for p in changed if matches(p,shared)]
  inventory={x['path'] for x in row.get('source_files',[])}
  row['relevant_added_or_uninventoried_paths']=[p for p in set(row['direct_scope_changed_paths']+row['shared_scope_changed_paths']) if p not in inventory]
  if row.get('accepted_revision') and row.get('envelope_revision')!=row['accepted_revision']:
   row['execution_envelope_acceptance_revision_difference']={'note':'Different recorded revisions; retain both and require the existing integration receipt, not automatic invalidation.','changed_paths':git('diff','--name-only',row['envelope_revision'],row['accepted_revision'],'--','apps','internal','adapters','migrations').splitlines()}
 row.update(decision.get(c,{'reuse_assessment':'OPEN_CASE_NO_PASS_TO_REUSE','later_evidence':[],'minimal_next_check':'Original full required gate remains open; this source audit does not execute or close it.','reason':'Canonical non-PASS status preserved.'}))
row_summary=[{k:r.get(k) for k in ['case','title','historical_status','accepted_mode','required_mode','accepted_revision','envelope_revision','source_inventory_count','changed_inventory_paths','direct_production_changed_paths','shared_scope_changed_paths','relevant_added_or_uninventoried_paths','reuse_assessment','later_evidence','minimal_next_check','reason','inventory_completeness']}|{'acceptance_refs':[x['ref'] for x in r['evidence_refs'] if '/verifier/' in x['ref']]} for r in report['cases']]
result={'verdict':'READ_ONLY_VERSION_REUSE_AUDIT','target_source':target,'formal_acceptance':False,'historical_status_counts':report['historical_status_counts'],'recommendation_counts':dict(collections.Counter(x['reuse_assessment'] for x in row_summary)),'cases':row_summary,'deltas':deltas,'scope_patterns':groups,'shared_patterns':shared,'limitations':['Recommendations require root acceptance.','No new test, provider, native, private, S2 or adversarial execution.','Inventories prove sampled bytes only; omitted/new dependencies and actual installed service freshness remain UNKNOWN.','Compile/package success never substitutes for behavior coverage.']}
(OUT/'reuse-matrix.json').write_text(json.dumps(result,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
